"""Half-open integer interval utilities."""


def merge(intervals):
    """Merge overlapping and touching half-open intervals; returns sorted list of tuples."""
    filtered = [(s, e) for s, e in intervals if s < e]
    if not filtered:
        return []
    filtered.sort()
    merged = [filtered[0]]
    for s, e in filtered[1:]:
        cs, ce = merged[-1]
        if s <= ce:  # overlapping or touching
            if e > ce:
                merged[-1] = (cs, e)
        else:
            merged.append((s, e))
    return [tuple(pair) for pair in merged]


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    gaps = []
    cur = ws
    for s, e in merge(intervals):
        if e <= cur:
            continue
        if s > we:
            break
        if s > cur:
            gaps.append((cur, s))
        cur = e
        if cur >= we:
            break
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty half-open intervals covering one common point."""
    events = []
    append = events.append
    for s, e in intervals:
        if s < e:
            append((s, 1))
            append((e, -1))
    if not events:
        return 0
    # At equal coordinates, ends (-1) are processed before starts (1): half-open semantics.
    events.sort(key=lambda ev: (ev[0], ev[1]))
    depth = best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live (see README.md)."""

import time
from collections import OrderedDict


class TTLCache:
    """An LRU cache whose entries can expire after a per-entry lifetime."""

    _MISSING = object()

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.clock = clock
        # key -> (value, expires_at or None); ordered from least to most recent
        self._entries = OrderedDict()

    @staticmethod
    def _is_expired(expires_at, now):
        return expires_at is not None and now >= expires_at

    def _purge_expired(self):
        now = self.clock()
        dead = [
            key
            for key, (_, expires_at) in self._entries.items()
            if self._is_expired(expires_at, now)
        ]
        for key in dead:
            del self._entries[key]
        return len(dead)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self.clock()
        expires_at = None if ttl is None else now + ttl
        if key in self._entries:
            # Replace: restart lifetime and bump recency.
            del self._entries[key]
        else:
            # New key: drop expired entries first, then LRU-evict if needed.
            if len(self._entries) >= self.capacity:
                self._purge_expired()
            while len(self._entries) >= self.capacity:
                self._entries.popitem(last=False)
        self._entries[key] = (value, expires_at)

    def get(self, key, default=None):
        entry = self._entries.get(key, self._MISSING)
        if entry is self._MISSING:
            return default
        value, expires_at = entry
        if self._is_expired(expires_at, self.clock()):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._entries.get(key, self._MISSING)
        if entry is self._MISSING:
            return False
        _, expires_at = entry
        if self._is_expired(expires_at, self.clock()):
            del self._entries[key]
            return False
        return True

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator.

Grammar (lowest to highest precedence):

    expr    := term (('+' | '-') term)*
    term    := unary (('*' | '/' | '//' | '%') unary)*
    unary   := ('+' | '-') unary | power
    power   := atom ('**' unary)?          # right-associative
    atom    := NUMBER | '(' expr ')' | funcall
    funcall := ('min' | 'max' | 'abs') '(' [expr (',' expr)*] ')'

Number literals are ints or floats; all operators follow Python semantics.
Anything malformed raises ValueError; division/modulo by zero raises
ZeroDivisionError (naturally, via Python's operators).
"""


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in " \t\r\n\f\v":
            i += 1
            continue
        if c.isdigit() or (c == "." and i + 1 < n and text[i + 1].isdigit()):
            j = i
            while j < n and text[j].isdigit():
                j += 1
            is_float = False
            if j < n and text[j] == ".":
                is_float = True
                j += 1
                while j < n and text[j].isdigit():
                    j += 1
            literal = text[i:j]
            tokens.append(("num", float(literal) if is_float else int(literal)))
            i = j
            continue
        if c.isalpha():
            j = i
            while j < n and (text[j].isalnum()):
                j += 1
            tokens.append(("name", text[i:j]))
            i = j
            continue
        two = text[i:i + 2]
        if two in ("**", "//"):
            tokens.append(("op", two))
            i += 2
            continue
        if c in "+-*/%(),":
            tokens.append(("op", c))
            i += 1
            continue
        raise ValueError("unknown character %r" % c)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect_op(self, op):
        kind, val = self.peek()
        if kind != "op" or val != op:
            raise ValueError("expected %r" % op)
        return self.advance()

    def parse_expr(self):
        left = self.parse_term()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("+", "-"):
                self.advance()
                right = self.parse_term()
                left = left + right if val == "+" else left - right
            else:
                return left

    def parse_term(self):
        left = self.parse_unary()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("*", "/", "//", "%"):
                self.advance()
                right = self.parse_unary()
                if val == "*":
                    left = left * right
                elif val == "/":
                    left = left / right
                elif val == "//":
                    left = left // right
                else:
                    left = left % right
            else:
                return left

    def parse_unary(self):
        kind, val = self.peek()
        if kind == "op" and val in ("+", "-"):
            self.advance()
            operand = self.parse_unary()
            return -operand if val == "-" else +operand
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        kind, val = self.peek()
        if kind == "op" and val == "**":
            self.advance()
            exponent = self.parse_unary()  # right-associative
            return base ** exponent
        return base

    def parse_atom(self):
        kind, val = self.peek()
        if kind == "num":
            self.advance()
            return val
        if kind == "op" and val == "(":
            self.advance()
            value = self.parse_expr()
            self.expect_op(")")
            return value
        if kind == "name":
            self.advance()
            if val not in ("min", "max", "abs"):
                raise ValueError("unknown name %r" % val)
            self.expect_op("(")
            args = []
            kind, val = self.peek()
            if not (kind == "op" and val == ")"):
                args.append(self.parse_expr())
                while True:
                    kind, val = self.peek()
                    if kind == "op" and val == ",":
                        self.advance()
                        args.append(self.parse_expr())
                    else:
                        break
            self.expect_op(")")
            if val == "abs":
                if len(args) != 1:
                    raise ValueError("abs takes exactly one argument")
                return abs(args[0])
            if not args:
                raise ValueError("%s requires at least one argument" % val)
            return min(*args) if val == "min" else max(*args)
        raise ValueError("unexpected %s" % ("end of input" if kind is None else repr(val)))


def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("expected a string")
    tokens = _tokenize(text)
    if not tokens:
        raise ValueError("empty expression")
    parser = _Parser(tokens)
    result = parser.parse_expr()
    if parser.pos != len(parser.tokens):
        kind, val = parser.tokens[parser.pos]
        raise ValueError("unexpected %r" % val)
    return result

